effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
vec4 u_xlat1;
bool u_xlatb1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat7;
bool u_xlatb7;
float u_xlat8;
float u_xlat13;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.x = acScreenNorm.x;
    u_xlat1.x = u_xlat1.x + -0.5;
    u_xlat7 = _resolution.x / _resolution.y;
    u_xlat1.x = u_xlat7 * u_xlat1.x;
    u_xlat1.y = (-acScreenNorm.y) + 0.5;
    u_xlat1.xy = u_xlat1.xy + (-_position.xy);
    u_xlat13 = _angle * 0.0174532998;
    u_xlat2.x = sin(u_xlat13);
    u_xlat3.x = cos(u_xlat13);
    u_xlat4.x = (-u_xlat3.x);
    u_xlat4.y = u_xlat2.x;
    u_xlat4.z = u_xlat3.x;
    u_xlat1.z = dot(u_xlat1.xy, u_xlat4.yz);
    u_xlat1.x = dot(u_xlat1.xy, u_xlat4.xy);
    u_xlat1.xy = u_xlat1.xz * vec2(10.0, 10.0);
    u_xlat1.xy = u_xlat1.xy / vec2(_scale.x, _scale.y);
    u_xlat1.xy = floor(u_xlat1.xy);
    u_xlat1.x = abs(u_xlat1.x) + abs(u_xlat1.y);
    u_xlat1.x = u_xlat1.x * 0.5;
    u_xlatb7 = u_xlat1.x>=(-u_xlat1.x);
    u_xlat1.x = fract(u_xlat1.x);
    u_xlat1.x = (u_xlatb7) ? u_xlat1.x : (-u_xlat1.x);
    u_xlatb1 = 0.25>=u_xlat1.x;
    u_xlat1.x = u_xlatb1 ? 1.0 : float(0.0);
    u_xlat1 = u_xlat1.xxxx * _color;
    u_xlatb2.x = int(_blend_mode)==1;
    u_xlat3 = u_xlat0 * u_xlat1;
    u_xlat8 = (-u_xlat1.w) * u_xlat0.w + 1.0;
    u_xlat4 = u_xlat0 * vec4(u_xlat8);
    u_xlat4 = u_xlat1 * u_xlat3.wwww + u_xlat4;
    u_xlat2 = (u_xlatb2.x) ? u_xlat3 : u_xlat4;
    u_xlat3.xyz = u_xlat1.xyz;
    u_xlat1 = (int(_blend_mode) != 0) ? u_xlat2 : u_xlat3;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
